-- Icelandic names (all) and instructions (programme + bang-for-buck exercises)
-- for the exercise library; translated + proofread 2026-10-01. Idempotent.
update public.exercises x set name_is = v.n, instructions_is = coalesce(v.i, x.instructions_is)
from (values
('99bc30d8-e161-43be-88ad-3894d5cc6380'::uuid, 'Uppseta (¾)', array['Leggstu á gólfið og festu fæturna. Hnén eiga að vera bogin.','Settu hendurnar fyrir aftan höfuð eða við hlið höfuðsins. Þú byrjar með bakið í gólfinu. Þetta er upphafsstaðan.','Beygðu í mjöðmum og hrygg til að lyfta bolnum í átt að hnjánum.','Efst í hreyfingunni á bolurinn að vera hornréttur á gólfið. Snúðu hreyfingunni við og farðu aðeins ¾ af leiðinni niður.','Endurtaktu eins oft og mælt er með.']::text[]),
('df830ccc-d5e6-4032-a5b8-196595976e3f'::uuid, 'Aftanlæristeygja 90/90', null),
('dbc472ca-f3bd-4a82-ae61-5bbd291bb8d4'::uuid, 'Kviðkreppa í vél', null),
