('2bc5ed55-bd1b-4fc9-8a1a-855ffb2ea6d0'::uuid, 'Útrúll á kviðhjóli', null),
('01637d72-35d2-4cb0-a184-b8505987cef1'::uuid, 'Innanlæristeygja', null),
('37c04bb2-e17f-403d-8ea0-a6fe238558f3'::uuid, 'Nára- og innanlæristeygja', null),
('b21e6af6-af1d-47b7-8b5b-bfda9ed690bb'::uuid, 'Vindmylla með ketilbjöllu, framhald', null),
('77840bbd-0796-4f89-8bbd-0c0d93c8dbb5'::uuid, 'Hjólahreyfing á gólfi (air bike)', array['Leggstu á bakið á gólfið með mjóbakið þrýst niður í gólfið. Settu hendurnar við hlið höfuðsins en gættu þess að toga ekki í hálsinn. Lyftu síðan öxlunum upp í kviðkreppustöðu.','Lyftu hnjánum þannig að lærin séu hornrétt á gólfið og leggirnir samsíða gólfinu. Þetta er upphafsstaðan.','Hjólaðu nú hægt með fótunum: sparkaðu hægri fæti fram og dragðu vinstra hné að þér. Færðu hægri olnboga að vinstra hné með því að kreppa til hliðar um leið og þú andar frá þér.','Farðu aftur í upphafsstöðu og andaðu að þér.','Lyftu þér í kviðkreppu til hinnar hliðarinnar um leið og þú hjólar með fótunum, færðu vinstri olnboga að hægra hné og andaðu frá þér.','Haltu áfram til skiptis þar til þú hefur lokið ráðlögðum fjölda endurtekninga á hvora hlið.']::text[]),
('88e78516-589a-4d7c-ba16-9a9401810304'::uuid, 'Framlæristeygja á fjórum fótum', null),
