('bba47ed9-e5d4-48b7-9a89-d6a58431bba9'::uuid, 'Handleggjahringir', array['Stattu með beina handleggi út til hliðanna.','Gerðu litla hringi fram á við í 15 sekúndur.','Stækkaðu hringina smám saman í aðrar 15 sekúndur.','Snúðu við og endurtaktu í hina áttina.']::text[]),
