('de661b57-8816-4dd5-9b3d-c19a543c91e6'::uuid, 'Fótakreppa á æfingabolta', null),
('83d82342-6608-440e-b881-2f1ab52ea944'::uuid, 'Upphífing með teygjuaðstoð', null),
('ea0f4d96-3b56-429c-bc4e-7ba68f6810a0'::uuid, 'Góðan daginn með teygju (good morning)', null),
('5b5b69af-dcb9-430a-aa1a-d9bef8c83f3a'::uuid, 'Mjaðmatog með teygju (pull through)', null),
('54eeee97-f4b7-45d7-8111-ee3f348fcd0b'::uuid, 'Aðfærsla í mjöðm með teygju', null),
('ef64452e-6f05-4ead-be29-c2810933ea5f'::uuid, 'Teygjutog í sundur (band pull-apart)', array['Byrjaðu með beina handleggi fram fyrir þig og haltu í teygjuna með báðum höndum.','Byrjaðu hreyfinguna eins og í öfugu flugi og færðu hendurnar út til hliðanna.','Haltu olnbogunum beinum í gegnum hreyfinguna og færðu teygjuna að bringunni. Haltu öxlunum aftur á meðan á æfingunni stendur.','Staldraðu við þegar hreyfingunni er lokið og farðu svo aftur í upphafsstöðu með stjórn.']::text[]),
('5f0432eb-373d-44c5-9da4-363c413e4df8'::uuid, 'Teygjutog í sundur', array['Haltu í létta teygju í axlarhæð með beina handleggi.','Kreistu herðablöðin saman um leið og þú togar teygjuna í sundur.','Staldraðu stutt við og farðu svo hægt til baka.','Haltu öxlunum niðri, fjarri eyrunum.']::text[]),
('e6f6ab9c-700e-40d4-bbc1-99ca70d6aee1'::uuid, 'Liggjandi þríhöfðarétta með teygju (skull crusher)', null),
('a4b5c05f-1411-4872-b3e4-99e205bd1208'::uuid, 'Útrúll með stöng', null),
('b8c72c8d-f345-4142-bee7-42063ef37cf0'::uuid, 'Útrúll með stöng á hnjám', null),
('6c2d46f9-a51f-4175-9188-6ccc7ec4e272'::uuid, 'Bekkpressa með stöng, miðlungsgrip', array['Leggstu á flatan bekk. Taktu miðlungsbreitt grip (þannig að 90 gráðu horn myndist milli framhandleggja og upphandleggja í miðri hreyfingu), lyftu stönginni úr rekkanum og haltu henni beint yfir þér með beina handleggi. Þetta er upphafsstaðan.','Andaðu að þér og láttu stöngina síga hægt niður þar til hún snertir miðja bringuna.','Eftir stutta pásu skaltu þrýsta stönginni aftur í upphafsstöðu um leið og þú andar frá þér. Einbeittu þér að því að pressa með brjóstvöðvunum. Réttu úr handleggjunum, kreistu brjóstvöðvana efst í hreyfingunni, haltu í sekúndu og láttu stöngina svo síga hægt niður aftur. Ábending: Helst ætti að taka um tvöfalt lengri tíma að láta þyngdina síga en að lyfta henni.','Endurtaktu hreyfinguna eins oft og mælt er fyrir um.','Þegar þú ert búinn skaltu setja stöngina aftur í rekkann.']::text[]),
('88b2a391-0e4b-4a08-8b05-7c75f75ea3f6'::uuid, 'Framhallandi róður með stöng', null),
('088cea3e-eec9-4619-b402-abb797f97637'::uuid, 'Tvíhöfðakreppa með stöng', null),
('96d1fa53-879c-4ea3-be4b-f6d60121e153'::uuid, 'Tvíhöfðakreppa með stöng', null),
('be47a8a6-ad3c-4ee8-a7de-c9119b6340b1'::uuid, 'Tvíhöfðakreppa með stöng liggjandi á hallandi bekk', null),
('4c9491b1-1476-4168-ae33-8158451811e5'::uuid, 'Réttstöðulyfta með stöng', array['Stattu fyrir framan hlaðna stöng.','Haltu bakinu eins beinu og hægt er, beygðu hnén, hallaðu þér fram og gríptu um stöngina með miðlungsbreiðu yfirgripi (axlabreidd). Þetta er upphafsstaðan. Ábending: Ef erfitt er að halda stönginni með þessu gripi geturðu notað blandað grip eða lyftingaólar.','Byrjaðu lyftuna með því að spyrna með fótunum og rétta um leið úr bolnum á meðan þú andar frá þér. Í uppréttri stöðu skaltu þrýsta bringunni fram og draga herðablöðin aftur, eins og hermaður í réttstöðu.','Farðu aftur í upphafsstöðu með því að beygja hnén og halla bolnum fram um mjaðmir en halda bakinu beinu. Þegar lóðin snerta gólfið ertu aftur í upphafsstöðu og getur byrjað næstu endurtekningu.','Gerðu þann fjölda endurtekninga sem æfingaáætlunin segir til um.']::text[]),
('42245a7d-856f-42ae-80a2-69bca6e12eab'::uuid, 'Djúp hnébeygja með stöng', array['Best er að gera þessa æfingu í hnébeygjurekka af öryggisástæðum. Settu stöngina í rekkann rétt fyrir neðan axlarhæð. Þegar hæðin er rétt og búið er að hlaða stöngina skaltu stíga undir hana og leggja hana þvert yfir aftanverðar axlirnar (rétt fyrir neðan hálsinn).','Haltu í stöngina með báðum höndum og lyftu henni úr rekkanum með því að spyrna með fótunum og rétta úr bolnum um leið.','Stígðu frá rekkanum og stilltu fótunum í axlabreidd með tærnar aðeins út á við. Haltu höfðinu uppi og bakinu beinu allan tímann. Þetta er upphafsstaðan.','Láttu stöngina síga hægt með því að beygja hnén og setjast aftur með mjöðmunum, með beina líkamsstöðu og höfuðið uppi. Farðu niður þar til aftanlærin hvíla á kálfunum. Andaðu að þér á leiðinni niður.','Lyftu stönginni um leið og þú andar frá þér með því að spyrna í gólfið með hælunum eða miðjum fætinum, rétta úr fótunum og mjöðmunum og fara aftur í upphafsstöðu.','Endurtaktu eins oft og mælt er með.']::text[]),
('4aa6f1c1-37a6-4df6-b4ed-a85b102f949b'::uuid, 'Mjaðmalyfta á gólfi með stöng', null),
('6edbee50-3073-4695-b9fe-f13b35e7c4d0'::uuid, 'Gálgabekkpressa með stöng (guillotine)', null),
('ea908b94-a35b-4287-8696-a49a995120b7'::uuid, 'Hack-hnébeygja með stöng', null),
('b1396718-5447-49d2-8d96-42ca2f4cff0a'::uuid, 'Mjaðmalyfta við bekk með stöng', array['Sestu á gólfið með bekk beint fyrir aftan þig og hlaðna stöng yfir fótunum. Þykk stöng eða púði á stönginni getur dregið verulega úr óþægindum.','Rúllaðu stönginni þannig að hún sé beint yfir mjöðmunum og hallaðu þér aftur upp að bekknum þannig að herðablöðin séu nálægt brún hans.','Byrjaðu hreyfinguna með því að spyrna í gegnum fæturna og ýta mjöðmunum beint upp í stöngina. Þyngdin á að hvíla á herðablöðunum og fótunum. Réttu eins langt og þú getur úr mjöðmunum og farðu síðan aftur í upphafsstöðu.']::text[]),
('86709c2c-9c94-45ed-89d8-2e31bd6c02d8'::uuid, 'Bekkpressa með stöng á hallandi bekk, miðlungsgrip', null),
('46049d76-9603-4c80-8ec4-0aa5addf6004'::uuid, 'Axlalyfta með stöng á hallandi bekk', null),
('61270598-bbeb-4415-82a7-cbd4107b7dad'::uuid, 'Framstig með stöng', null),
('9439387a-1d60-4983-a21b-0ffbb6dd678f'::uuid, 'Axlapressa með stöng', array['Stattu með fætur í axlabreidd og stöngina í rekka í hæð við viðbein.','Gríptu um stöngina aðeins breiðar en í axlabreidd.','Pressaðu stönginni upp fyrir höfuð þar til handleggirnir eru beinir.','Láttu stöngina síga aftur niður að viðbeinum með stjórn.','Haltu kviðnum spenntum og forðastu að sveigja bakið mikið aftur.']::text[]),
('eb962d1c-9001-4c6e-a75e-88becb256f04'::uuid, 'Róður fyrir afturaxlir með stöng', null),
