('a29678ca-54f4-4185-9872-a8950c712093'::uuid, 'Hliðarhnébeygja með stöng', null),
('899998b7-9040-4668-bfc2-10a40c1af9e5'::uuid, 'Hnébeygja með stöng', null),
('d39d3170-2043-40c4-97f3-447e9bd2a2a8'::uuid, 'Hnébeygja niður á bekk með stöng', null),
('e2b7e899-d9fb-4f32-aa72-48d2570a39b8'::uuid, 'Uppstig með stöng', null),
