('c98b5f5a-8190-472b-8985-462e4b500fbc'::uuid, 'Eldflaugarhopp', array['Stattu afslappaður með fætur í axlabreidd og handleggina nálægt líkamanum.','Farðu hálfa leið niður í hnébeygju og spyrntu þér kröftuglega upp eins hátt og þú getur.','Réttu alveg úr öllum líkamanum og teygðu hendurnar eins hátt upp og þú getur. Þegar þú lendir skaltu láta fæturna taka við högginu.']::text[]),
('7b57d0b6-72f4-48fc-bc6a-79f8f3bd9efa'::uuid, 'Standandi kálfalyfta með rugg, með stöng', null),
('322499d3-c6db-45c3-9ac0-a9c555e94a49'::uuid, 'Rocky-upphífingar/niðurtog', null),
('5c25deeb-f7e8-4602-8322-a9180a7a69e9'::uuid, 'Rúmensk réttstöðulyfta', array['Stattu með stöngina í mjaðmarhæð og grip í axlabreidd.','Ýttu mjöðmunum aftur og láttu stöngina síga meðfram fótleggjunum með örlitla beygju í hnjánum.','Farðu niður þar til þú finnur góða teygju í aftanlærunum.','Ýttu mjöðmunum fram til að standa aftur upp.','Haltu stönginni nálægt líkamanum og bakinu beinu.']::text[]),
('ea16dd23-a825-44f5-9571-6e0c0e0085f5'::uuid, 'Rúmensk réttstöðulyfta af upphækkun', null),
