('3c8b90aa-5295-4f7d-b88f-877603f6a4a5'::uuid, 'Kviðkreppa með kaðli í kapli', null),
('40dc8701-29ae-4f1e-8c47-d7df18d55038'::uuid, 'Sippa', null),
('e12b792d-a158-4651-95d4-688b12258fe8'::uuid, 'Niðurtog með beinum handleggjum og kaðli', null),
('1e5665e2-c74e-451b-bb4b-551509ffbb33'::uuid, 'Axlateygja, hringur um heiminn', null),
('1a3bb35d-f749-4f34-91f9-51bc414f7b15'::uuid, 'Róðravél', null),
('08c21ab2-1ce0-4260-86e0-6c0b6ff110cc'::uuid, 'Róður í róðravél', array['Sestu í róðravélina. Hælarnir eiga að hvíla þægilega á fótplötunum og ólarnar að vera festar. Veldu forrit ef við á. Sittu bein(n) og hallaðu þér fram um mjaðmir.','Róðurinn skiptist í þrjá fasa. Í fyrsta fasa rennurðu þér fram: hnén eru bogin og upp við bringuna og efri hluti líkamans hallar örlítið fram en þú heldur góðri líkamsstöðu. Næst spyrnirðu í fótplöturnar og réttir úr fótunum um leið og þú dregur hendurnar að efri hluta kviðar og dregur axlirnar aftur. Notaðu aðallega fóta- og mjaðmavöðvana til að hlífa bakinu.','Í endurheimtarfasanum réttirðu úr handleggjunum, beygir hnén og færir líkamann aftur fram og byrjar þannig næsta tog.']::text[]),
('087d1b87-77f5-4180-9a43-f7580e9d9414'::uuid, 'Hlauparateygja', null),
('76b11cbd-ac70-497b-8393-b1fffaa8ba81'::uuid, 'Hlaup', null),
('320ef9d9-eeab-450f-b5f6-3fbc6a369984'::uuid, 'Hlaup á hlaupabretti', null),
('a953085a-f40e-4163-8367-1a93c79ef7ce'::uuid, 'Rússneskur snúningur', array['Sestu á gólfið með bogin hné, hallaðu þér örlítið aftur og lyftu fótunum frá gólfinu.','Spenntu greipar eða haltu á lóði í bringuhæð.','Snúðu bolnum til annarrar hliðar og færðu lóðið niður við hlið mjaðmarinnar.','Snúðu þér yfir á hina hliðina með stjórn.']::text[]),
('0fa63edf-da03-45c2-9d18-fae645ee2aa8'::uuid, 'Sandpokalyfta', null),
('fea2b390-efb7-465b-9e38-4b66875d7b04'::uuid, 'Herðablaðaupphífing', null),
('cee3dfec-a774-42df-8c4f-0532813f896f'::uuid, 'Herðablaðaarmbeygjur', null),
('7ace83cd-8fd9-4fbe-9f7f-b95587716143'::uuid, 'Skærisspark', null),
('32ddb42a-0acc-4cb2-9553-07eb087ad71e'::uuid, 'Skærahopp', array['Farðu í framstigsstöðu með annan fótinn fram og hnéð bogið og aftara hnéð nánast við gólfið.','Gættu þess að fremra hnéð sé yfir miðjum fætinum. Réttu úr báðum fótum og stökktu eins hátt og þú getur og sveiflaðu handleggjunum til að fá meiri lyftu.','Skiptu um fótastöðu í loftinu þannig að fremri fóturinn fari aftur og aftari fóturinn fram.','Lentu í framstigsstöðu þannig að fæturnir taki við högginu og endurtaktu.']::text[]),
('cb755073-4856-4daa-8717-5c2a008c2da6'::uuid, 'Sitjandi fótakreppa með teygju', null),
('8adad542-4100-4730-af83-b6da9eb11fc9'::uuid, 'Sitjandi axlapressa með stöng', null),
('c8b69179-eda5-4a14-808f-79e581e002e7'::uuid, 'Sitjandi snúningur með stöng', null),
('d428371f-c9dd-4218-be6c-2f3161e9bb25'::uuid, 'Sitjandi þríhöfðarétta í framhalla með handlóði, önnur hönd', null),
('e632609f-774c-401e-be20-30763417c70d'::uuid, 'Sitjandi afturaxlalyfta í framhalla', null),
('0b5f4eb9-3c58-4e6d-b96b-d921f575c53a'::uuid, 'Sitjandi þríhöfðarétta í framhalla með tveimur handlóðum', null),
('e320c5f9-7eab-43fe-9965-1a4eacb2ef1a'::uuid, 'Sitjandi tvíhöfðateygja', null),
('48aaa703-709d-4c91-af57-a7a69a133829'::uuid, 'Sitjandi róður í kapli', array['Sestu við róðrarstöðina í kapalvélinni með fæturna á fótplötunni og hnén örlítið bogin.','Gríptu um V-handfangið eða beina stöng.','Dragðu handfangið að neðri hluta bringunnar og kreistu herðablöðin saman.','Réttu úr handleggjunum aftur með stjórn og haltu bolnum uppréttum.']::text[]),
('cc80f7bd-d40e-47d3-9dd3-98a3888ddb62'::uuid, 'Sitjandi róður í kapli', array['Í þessa æfingu þarftu róðrarvél með neðri kapli og V-handfangi. Athugið: Með V-handfanginu færðu hlutlaust grip þar sem lófarnir snúa hvor að öðrum. Sestu í vélina og settu fæturna á fótplötuna eða þverslána með hnén örlítið bogin, ekki læst.','Hallaðu þér fram með bakið í eðlilegri stöðu og gríptu um V-handfangið.','Með beina handleggi skaltu draga þig aftur þar til bolurinn myndar 90 gráðu horn við fæturna. Mjóbakið á að vera örlítið fett og bringan fram. Þú átt að finna góða teygju í breiðu bakvöðvunum á meðan þú heldur handfanginu fyrir framan þig. Þetta er upphafsstaðan.','Haltu bolnum kyrrum og dragðu handfangið að þér, með handleggina nálægt líkamanum, þar til það snertir kviðinn. Andaðu frá þér á meðan. Á þessum tímapunkti áttu að kreista bakvöðvana fast. Haltu samdrættinum í sekúndu og farðu hægt aftur í upphafsstöðu um leið og þú andar að þér.','Endurtaktu eins oft og mælt er með.']::text[]),
('b317b359-4622-41f5-b827-54bba454fe93'::uuid, 'Sitjandi axlapressa í kapli', null),
('43e883c5-cb10-494c-848a-6347723dad9b'::uuid, 'Sitjandi kálfalyfta', null),
('7df05ab4-7407-4a19-86a5-b9aa2b96dc28'::uuid, 'Sitjandi kálfateygja', null),
('1a7165dd-4995-4375-8958-b258390c1e34'::uuid, 'Sitjandi einbeitingarkreppa með stöng, þröngt grip', null),
