('43aad8a4-853e-404b-969e-bda9d14af9b7'::uuid, 'Sitjandi handlóðapressa', null),
('9b2113b0-0112-4373-bf3c-8290afb275bd'::uuid, 'Sitjandi axlapressa með handlóðum', array['Sestu á bekk með bakstuðningi og haltu á handlóði í hvorri hendi í axlarhæð.','Pressaðu báðum handlóðunum upp fyrir höfuð þar til handleggirnir eru beinir.','Láttu handlóðin síga aftur niður í axlarhæð.','Haltu bakinu upp við bakpúðann allan tímann.']::text[]),
('34725064-11b8-4980-b6fd-249ce5294b54'::uuid, 'Sitjandi hnédráttur á flötum bekk', array['Sestu á bekk með fæturna rétta fram, rétt neðan við lárétta stöðu, og haltu um hliðar bekkjarins. Bolurinn hallar aftur í um 45 gráður. Þetta er upphafsstaðan.','Dragðu hnén að þér og færðu bolinn nær þeim um leið. Andaðu frá þér á meðan.','Staldraðu við í sekúndu og farðu svo aftur í upphafsstöðu um leið og þú andar að þér.','Endurtaktu eins oft og mælt er með.']::text[]),
