('af3d7212-0407-4c69-9a41-8d5ac7c2c30a'::uuid, 'Sund', array['Farðu út í laugina og veldu sundaðferð (skriðsund, baksund, bringusund o.s.frv.).','Syntu á jöfnum hraða og einbeittu þér að rólegri öndun.','Notaðu lotur af mismunandi vegalengdum til að breyta ákefðinni.','Ljúktu með nokkrum rólegum ferðum.']::text[]),
